              </div>
            </div>

            {/* Right Panel */}
            <div style={{
              flex: 1,
              paddingLeft: "4vw",
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
              overflow: "hidden",
              minHeight: 180,
            }}>
              <div key={activeIdx} style={{ animation: "fadeSlideIn 0.45s ease forwards" }}>

                {/* Active insight */}
                <div style={{
                  borderLeft: "3px solid #e53e3e",
                  paddingLeft: 20,
                  marginBottom: 28,
